(args, got) => {
    const nums = args[0];
    if (!Array.isArray(got) || got.length === 0 || got[0] === null || got[0] === undefined) return false;
    const root = { v: got[0], l: null, r: null };
    const q = [root];
    let head = 0, i = 1;
    while (i < got.length) {
      const p = q[head++];
      if (!p) return false;
      for (const side of ["l", "r"]) {
        if (i >= got.length) break;
        if (got[i] !== null) { const c = { v: got[i], l: null, r: null }; p[side] = c; q.push(c); }
        i++;
      }
    }
    const order = [];
    let ok = true;
    const walk = (t) => {
      if (!t) return 0;
      const hl = walk(t.l);
      order.push(t.v);
      const hr = walk(t.r);
      if (Math.abs(hl - hr) > 1) ok = false;
      return 1 + Math.max(hl, hr);
    };
    walk(root);
    return ok && order.length === nums.length && order.every((v, k) => v === nums[k]);
  }

